JSON.stringify({theme:'light', 主界面不达标:main, 含弹窗不达标:dlg},null,1)

const cv=document.createElement('canvas');cv.width=cv.height=1;const cx=cv.getContext('2d',{willReadFrequently:true});
const lum=c=>{cx.fillStyle='#000';cx.fillStyle=c;cx.fillRect(0,0,1,1);const d=cx.getImageData(0,0,1,1).data;
 const v=[d[0],d[1],d[2]].map(x=>{x/=255;return x<=.03928?x/12.92:Math.pow((x+.055)/1.055,2.4);});return .2126*v[0]+.7152*v[1]+.0722*v[2];};
const run=()=>{const bgOf=el=>{let n=el,c=getComputedStyle(n).backgroundColor;while((c==='rgba(0, 0, 0, 0)'||c==='transparent')&&n.parentElement){n=n.parentElement;c=getComputedStyle(n).backgroundColor;}return c;};
 const bad=[];for(const el of document.querySelectorAll('body *')){if(el.offsetParent===null&&el.tagName!=='BODY')continue;
  const t=[...el.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');if(!t)continue;
  const cs=getComputedStyle(el);const a=lum(cs.color),b=lum(bgOf(el));const r=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);
  const size=parseFloat(cs.fontSize),wt=parseInt(cs.fontWeight)||400;const need=(size>=24||(size>=18.66&&wt>=700))?3:4.5;
  if(r<need)bad.push({txt:t.slice(0,18),size,r:Math.round(r*100)/100,fg:cs.color,bg:bgOf(el)});}
 return bad;};
const rs=getComputedStyle(document.documentElement);
document.querySelector('#history button')?.click(); await new Promise(r=>setTimeout(r,1800));
const main=run();
document.querySelector('#findings button')?.click(); await new Promise(r=>setTimeout(r,2500));
const dlg=run();
document.getElementById('evidence-dialog').close();
JSON.stringify({theme:document.documentElement.dataset.theme, muted:rs.getPropertyValue('--muted').trim(), signal_pale:rs.getPropertyValue('--signal-pale').trim(), 主界面不达标:main, 含弹窗不达标:dlg},null,1)

